 row['flags']=priority.get(row['state'],[])+row['flags'];results=[x for x in links if row['state'] in x['states']];row['source_access']={'success':sum(isinstance(x['status'],int) and 200<=x['status']<400 for x in results),'broken':[x['url'] for x in results if x['status'] in [404,410]],'unverified':[{'url':x['url'],'status':x['status']} for x in results if not isinstance(x['status'],int) or x['status']>=400]}
